{let hit=0;const t=Date.now();while(Date.now()-t<10000){const l1=byTitle('发票登记');if(l1){const b=[...l1.querySelectorAll('button')].filter(vis).find(x=>tt(x)==='选择系统发票');if(b){b.click();hit=1;break}}await sleep(300)}if(!hit)throw new Error('选择系统发票按钮10s未找到 '+forensics());await sleep(500)}
