{let hit=0;const t=Date.now();while(Date.now()-t<10000){const l1=byTitle('发票登记');if(l1){const b=[...l1.querySelectorAll('button')].filter(vis).find(x=>tt(x)==='确定');if(b){b.click();hit=1;break}}await sleep(300)}if(!hit)throw new Error('弹层1确定10s未找到 '+forensics())}
// ⑦ 等弹层1 关闭=登记完成（allocationInvoiceFee check→submit）；300ms 采集 toast（406 等错误 3s 即逝）
{const errs=[];const t=Date.now();while(Date.now()-t<30000){const toasts=[...document.querySelectorAll('.el-message')].filter(vis).map(m=>(m.textContent||'').trim().slice(0,80));for(const x of toasts)if(errs.indexOf(x)<0)errs.push(x);if(!byTitle('发票登记')){await sleep(800);return{ok:true,full:true,ms:Date.now()-T0,toasts:errs}}await sleep(300)}throw new Error('发票登记30s未完成 toasts='+JSON.stringify(errs).slice(0,200)+' '+forensics())}})()

(async()=>{const vis=e=>!!(e&&e.getClientRects().length);const sleep=ms=>new Promise(r=>setTimeout(r,ms));const n=x=>(x.textContent||'').replace(/\s+/g,'');const wrap=()=>[...document.querySelectorAll('.el-dialog__wrapper')].filter(vis).find(w=>[...w.querySelectorAll('.el-form-item__label')].some(l=>n(l).replace(/^\*/,'')==='发票币制'));
