const items=()=>[...w.querySelectorAll('.el-form-item')].filter(vis);const lb=f=>n(f.querySelector('.el-form-item__label')).replace(/^\*/,'');const fi=()=>items().find(f=>lb(f)==='发票币制');const cur=()=>{const f=fi();const i=f?f.querySelector('input'):null;return i?(i.value||''):''};
let ocr='';const t1=Date.now();while(Date.now()-t1<12000){const nf=items().find(f=>lb(f)==='发票号码');const ni=nf?nf.querySelector('input'):null;if(ni&&(ni.value||'')){ocr=ni.value;break}await sleep(400)}
