let via='default';if(cur()!=='CNY'){if(!(await pick('CNY')))throw new Error('币制CNY选项未现');via='picked';const t2=Date.now();while(Date.now()-t2<3000){if(cur()==='CNY')break;await sleep(250)}}
if(cur()!=='CNY')throw new Error('币制非CNY cur='+cur());
