(async()=>{const T0=Date.now();const vis=e=>!!(e&&e.getClientRects().length);const sleep=ms=>new Promise(r=>setTimeout(r,ms));const tt=x=>(x.textContent||'').replace(/\s+/g,'');const wraps=()=>[...document.querySelectorAll('.el-dialog__wrapper,.el-message-box__wrapper')].filter(vis);const title=x=>((x.querySelector('.el-dialog__title,.el-message-box__title')||{textContent:''}).textContent||'').trim();const btnIn=(w,t)=>[...w.querySelectorAll('button')].filter(vis).find(b=>tt(b)===t);const toasts=()=>[...document.querySelectorAll('.el-message')].filter(vis).map(m=>(m.textContent||'').trim().slice(0,60));const forensics=()=>JSON.stringify({dlgs:wraps().map(x=>title(x).slice(0,10)+':'+tt(x).slice(0,36)),toasts:toasts()}).slice(0,300);const notes=[];const errs=[];const cap=()=>{for(const x of toasts())if(errs.indexOf(x)<0)errs.push(x)};const famOpen=()=>wraps().some(x=>{const s=title(x)+tt(x);return s.indexOf('发票')>=0||s.indexOf('上传')>=0});
const isConfirm=w=>{const t=tt(w),ti=title(w);return t.indexOf('您确认')>=0||t.indexOf('上传吗')>=0||w.classList.contains('el-message-box__wrapper')||(!!ti&&ti.indexOf('发票')<0&&ti.indexOf('选择')<0)};
// ① 二次确认框 → 确定（12s 未现留痕=无此层直接进③）
{let hit=0;const t=Date.now();while(Date.now()-t<12000){const w=wraps().find(x=>isConfirm(x)&&btnIn(x,'确定'));if(w){btnIn(w,'确定').click();hit=1;notes.push('c1:'+(title(w)||'mb'));break}cap();await sleep(300)}if(!hit)notes.push('no-confirm')}
// ② 等二次确认层消散，给上传一拍（最多8s）
{const t=Date.now();while(Date.now()-t<8000){cap();if(!wraps().some(x=>isConfirm(x)))break;await sleep(400)}}
// ③+④ 完成登记确定：优先发票登记弹层footer确定，退而任何可见确定；8s不闭合重点（≤4次）
{let tries=0;while(tries<4){const l1=wraps().find(x=>title(x).indexOf('发票登记')>=0);const b=(l1&&btnIn(l1,'确定'))||wraps().map(w=>btnIn(w,'确定')).find(Boolean);if(!b){notes.push('no-ok@'+tries);break}b.click();tries++;notes.push('ok'+tries);
const t=Date.now();while(Date.now()-t<8000){cap();if(!famOpen()){await sleep(700);cap();return{ok:true,full:true,notes:notes.join(','),ms:Date.now()-T0,toasts:errs}}await sleep(300)}
await sleep(1200)}
throw new Error('发票登记未完成 notes='+notes.join(',')+' toasts='+JSON.stringify(errs).slice(0,180)+' '+forensics())}})()

